try {
  const errors = [];    // block auto-saving, go to review
  const warnings = [];  // saved, but flagged
  const OWNER = 'northwind demo services';  // lowercase name of the company this inbox belongs to
  const MODE = 'receiving';                 
  const isBlank = v => v === null || v === undefined || (typeof v === 'string' && /^(|null|n\/a|na|unknown|none|-)$/i.test(v.trim()));
  const num = v => {
    if (isBlank(v)) return null;
    if (typeof v === 'number') return Number.isFinite(v) ? v : NaN;
    const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
    return Number.isFinite(n) ? n : NaN;
  };
  const near = (a, b, tol = 0.02) => Math.abs(a - b) <= tol;

  // 1. Did the AI call itself succeed?
  if ($json.error) errors.push('AI call failed: ' + (typeof $json.error === 'string' ? $json.error : ($json.error.message || 'unknown error')));
  const fr = $json.finishReason;
  if (fr && fr !== 'STOP') errors.push('AI response incomplete or blocked (' + fr + ')');

  // 2. Extract and parse JSON (tolerates fences or extra text)
  const raw = ($json.content?.parts ?? []).map(p => p.text ?? '').join('');
  let d = null;
  if (!raw) { if (!$json.error) errors.push('empty AI response'); }
  else {
    const m = raw.replace(/```json|```/g, '').match(/\{[\s\S]*\}/);
    try { d = JSON.parse(m ? m[0] : raw); } catch (e) { errors.push('invalid JSON from AI'); }
  }
  if (d && (typeof d !== 'object' || Array.isArray(d))) { errors.push('AI did not return an object'); d = null; }

  let subtotal = null, tax = null, total = null;
  if (d) {
    // 3. Required text fields
    for (const f of ['supplier', 'invoice_number', 'invoice_date', 'currency']) {
      if (isBlank(d[f])) errors.push('missing ' + f);
    }
    if (!isBlank(d.supplier) && String(d.supplier).trim().length < 2) errors.push('supplier name too short');

    // 3b. Parties swapped?
    const sup = String(d.supplier ?? '').toLowerCase();
    const bill = String(d.bill_to ?? '').toLowerCase();
    if (sup && bill && sup === bill) errors.push('supplier equals bill-to');
    if (MODE === 'receiving') {
      if (sup.includes(OWNER)) errors.push('supplier is the owner (parties swapped?)');
      else if (bill && !bill.includes(OWNER)) warnings.push('invoice is not addressed to ' + OWNER);
    } else {
      if (bill.includes(OWNER)) errors.push('bill-to is the owner (parties swapped?)');
      else if (sup && !sup.includes(OWNER)) warnings.push('supplier is not ' + OWNER);
    }

    // 4. Numbers
    subtotal = num(d.subtotal); tax = num(d.tax); total = num(d.total);
    for (const [k, v] of [['subtotal', subtotal], ['tax', tax], ['total', total]]) {
      if (Number.isNaN(v)) errors.push(k + ' is not a number');
    }
    if (total === null) errors.push('missing total');
    else if (!Number.isNaN(total)) {
      if (total === 0) errors.push('total is zero');
      if (total < 0) warnings.push('negative total (credit note?)');
      if (Math.abs(total) > 100000) warnings.push('unusually large total');
    }
    if (subtotal !== null && !Number.isNaN(subtotal) && subtotal < 0) warnings.push('negative subtotal');
    if (tax !== null && !Number.isNaN(tax) && tax < 0) warnings.push('negative tax');

    // 5. Date
    if (!isBlank(d.invoice_date)) {
      const ds = String(d.invoice_date);
      const dt = /^\d{4}-\d{2}-\d{2}$/.test(ds) ? new Date(ds + 'T00:00:00Z') : null;
      if (!dt || Number.isNaN(dt.getTime()) || dt.toISOString().slice(0, 10) !== ds) errors.push('invalid date format (expected YYYY-MM-DD)');
      else {
        const days = (Date.now() - dt.getTime()) / 86400000;
        if (days < -1) errors.push('invoice date is in the future');
        if (days > 730) warnings.push('invoice is over 2 years old');
        const [, mm, dd] = ds.split('-').map(Number);
        if (dd <= 12 && dd !== mm) warnings.push('date could be read as day/month swapped (' + ds + ')');
      }
    }

    // 6. Currency
    if (!isBlank(d.currency)) {
      const c = String(d.currency).trim();
      if (!/^[A-Z]{3}$/.test(c)) errors.push('bad currency code');
      else if (!['USD','EUR','GBP','NGN','CAD','AUD','CHF','JPY','CNY','INR','ZAR','KES','GHS','AED','BRL','MXN'].includes(c)) warnings.push('uncommon currency ' + c);
    }

    // 7. Invoice number sanity
    if (!isBlank(d.invoice_number) && String(d.invoice_number).trim().length > 40) warnings.push('invoice number unusually long');

    // 8. Line items
    const items = Array.isArray(d.line_items) ? d.line_items : [];
    if (!items.length) warnings.push('no line items extracted');
    let sum = 0, itemsOk = items.length > 0;
    items.forEach((it, i) => {
      const q = num(it?.quantity), p = num(it?.unit_price), a = num(it?.amount);
      if (a === null || Number.isNaN(a)) { errors.push(`line ${i + 1}: amount missing or not a number`); itemsOk = false; return; }
      sum += a;
      if (a < 0) warnings.push(`line ${i + 1}: negative amount`);
      if (q !== null && p !== null && !Number.isNaN(q) && !Number.isNaN(p) && !near(q * p, a, Math.max(0.05, Math.abs(a) * 0.005))) {
        errors.push(`line ${i + 1}: quantity x unit price (${(q * p).toFixed(2)}) does not equal amount (${a})`);
      }
      if (isBlank(it?.description)) warnings.push(`line ${i + 1}: no description`);
    });
    if (itemsOk && subtotal !== null && !Number.isNaN(subtotal) && !near(sum, subtotal)) errors.push(`line items sum (${sum.toFixed(2)}) does not equal subtotal (${subtotal})`);

    // 9. Totals
    const t = Number.isNaN(tax) ? null : (tax ?? 0);
    if (total !== null && !Number.isNaN(total) && t !== null) {
      if (subtotal !== null && !Number.isNaN(subtotal)) {
        if (!near(subtotal + t, total)) errors.push(`subtotal + tax (${(subtotal + t).toFixed(2)}) does not equal total (${total})`);
      } else if (itemsOk && !near(sum + t, total)) {
        errors.push(`line items + tax (${(sum + t).toFixed(2)}) does not equal total (${total})`);
      }
      if (subtotal > 0 && tax !== null && tax / subtotal > 0.3) warnings.push('tax rate above 30%');
    }

    // 10. Confidence
    const conf = num(d.confidence);
    if (conf === null || Number.isNaN(conf)) warnings.push('no confidence score');
    else if (conf < 80) errors.push(`low confidence (${conf})`);
  }

  const mail = (() => { try { return $('Gmail Trigger').item.json; } catch (e) { return {}; } })();
  const key = d ? `${String(d.supplier ?? '').trim()}|${String(d.invoice_number ?? '').trim()}`.toLowerCase() : '';
  return { json: {
    supplier: d?.supplier ?? '',
    bill_to: d?.bill_to ?? '',
    invoice_number: d?.invoice_number ?? '',
    invoice_date: d?.invoice_date ?? '',
    currency: d?.currency ?? '',
    subtotal, tax, total,
    confidence: d?.confidence ?? null,
    line_items: JSON.stringify(d?.line_items ?? []),
    status: errors.length ? 'needs_review' : 'valid',
    issues: errors.join('; '),
    warnings: warnings.join('; '),
    email_from: mail.from?.text ?? '',
    email_subject: mail.subject ?? '',
    received_at: mail.date ?? '',
    dedupe_key: key
  } };
} catch (e) {
  return { json: { status: 'needs_review', issues: 'validator crashed: ' + e.message, warnings: '', dedupe_key: '' } };
}
